#[cfg(test)]
mod luts_tests {
    use super::CYCLES_LUT_WORDS;

    #[test]
    fn lut_total_length() {
        assert_eq!(CYCLES_LUT_WORDS.len(), 29_712);
    }

    #[test]
    fn lut_boundary_spot_checks() {
        assert_eq!(CYCLES_LUT_WORDS[0], 0xfffffeffu32, "lut_e[0]");
        assert_eq!(CYCLES_LUT_WORDS[16383], 0x4e57606au32, "lut_e[16383]");
        assert_eq!(CYCLES_LUT_WORDS[16384], 0xffffffffu32, "lut_eavg[0]");
        assert_eq!(CYCLES_LUT_WORDS[17407], 0x68bd701du32, "lut_eavg[1023]");
        assert_eq!(CYCLES_LUT_WORDS[17408], 0xfafbffffu32, "lut_small[0]");
        assert_eq!(CYCLES_LUT_WORDS[18447], 0x000b000bu32, "lut_small[1039]");
        assert_eq!(CYCLES_LUT_WORDS[18448], 0x00003c00u32, "lut_thin[0].x");
        assert_eq!(CYCLES_LUT_WORDS[18449], 0x00003c00u32, "lut_thin[0].y");
        assert_eq!(CYCLES_LUT_WORDS[18450], 0x00003c00u32, "lut_thin[0].z");
        assert_eq!(CYCLES_LUT_WORDS[19983], 0x000098fdu32, "lut_thin[511].z");
        assert_eq!(CYCLES_LUT_WORDS[19984], 0x000003ffu32, "lut_ior_s[0]");
        assert_eq!(CYCLES_LUT_WORDS[28175], 0x00000000u32, "lut_ior_s[8191]");
        assert_eq!(CYCLES_LUT_WORDS[28176], 0x0000233fu32, "lut_sheen[0]");
        assert_eq!(CYCLES_LUT_WORDS[29711], 0x35783595u32, "lut_sheen[1535]");
    }
}

